cands=set()
for c in chars:
  for f in (lambda s:s, lambda s:N('NFD',s), lambda s:N('NFC',s), str.casefold, str.upper, str.lower, lambda s:N('NFD',s.casefold()), lambda s:N('NFC',s.casefold())):
    cands.add(f(c))
groups={}
