    """Regex for `glob`; anchored ones are matched against "/" + the relative path."""
    if not anchored:
        return _segment_regex(glob)
    return "".join("(?:/[^/]*)*" if seg == "**" else "/" + _segment_regex(seg)
                   for seg in glob.split("/"))


def _parse(text):
    """Return a list of (negate, dir_only, anchored, score, regex) rules."""
    rules = []
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith(";"):
            continue
        negate = line.startswith("!")
        if negate:
            line = line[1:]
        dir_only = line.endswith("/")
