"""Decide which files in a project tree are excluded by its .packignore files.

This is a pure-Python reimplementation of `packignore`, the legacy exclusion
engine. docs/PACKIGNORE.md describes it only loosely; the rules below are the
ones `packignore` actually applies:

* The tree is looked at as on a case- and normalization-insensitive file
  system: paths whose components are equal after Unicode case folding and
  canonical normalization are the same entry. The first spelling seen (in
  walk order) is kept, and for files the last contents win. A path that is
  both a file and a directory is an error.
* A file named exactly `.packignore` is read in a directory unless that
  directory is itself excluded. Its patterns apply to paths below it, after
  the patterns of `.packignore` files higher up.
* Lines are split with str.splitlines() and stripped of surrounding
  whitespace. Empty lines and lines starting with `;` are skipped (`#` is
  *not* a comment). A leading `!` negates. Trailing `/`s make the pattern
  match directories only; leading `/`s are dropped. The pattern is anchored to
  its `.packignore` directory if it had a leading `/` or contains a `/`,
  otherwise it matches names at any depth. Backslash is an ordinary character.
* Braces are then expanded: the first `{` and the first `}` after it enclose
  comma-separated alternatives (not re-expanded); the rest of the pattern is
  expanded recursively. `[` and `]` are literal.
* `*` matches any run of characters except `/`, `?` exactly one such
  character. In an anchored pattern a segment that is exactly `**` matches
  zero to three path components (so a trailing `/**` also matches the
  directory itself). Elsewhere `**` is just `*`.
* A path's status is decided by the last pattern matching the path itself;
  if none does, it inherits its parent directory's status. So a negation can
  re-include a file inside an excluded directory, but an excluded directory's
  own `.packignore` is never read.
"""

import os
import unicodedata


class PackignoreError(Exception):
    """The tree cannot be evaluated (e.g. a path is both a file and a directory)."""


def _fold(name):
    return unicodedata.normalize("NFD", unicodedata.normalize("NFD", name).casefold())


def _walk(root):
    """Return {path: contents-or-None} for the files under `root`, in walk order."""
    files = {}
    for dirpath, dirnames, filenames in os.walk(root):
        if os.path.samefile(dirpath, root) and ".git" in dirnames:
            dirnames.remove(".git")
        for name in filenames:
            full = os.path.join(dirpath, name)
            rel = os.path.relpath(full, root).replace(os.sep, "/")
            if name == ".packignore":
                with open(full, newline="") as f:
                    files[rel] = f.read()
            else:
                files[rel] = None
    return files


def _merge(files):
    """Merge entries the way a case/normalization-insensitive file system would."""
    dirs = {(): ()}  # folded parts -> spelled parts
    merged = {}  # folded parts -> [spelled path, contents]
    for rel, content in files.items():
        parts = rel.split("/")
        spelled = ()
        key = ()
        for part in parts[:-1]:
            key += (_fold(part),)
            if key in merged:
                raise PackignoreError(f"invalid tree: {'/'.join(merged[key][0])!r} is both a file "
                                      f"and a directory")
            if key not in dirs:
                dirs[key] = spelled + (part,)
            spelled = dirs[key]
        key += (_fold(parts[-1]),)
        if key in dirs:
            raise PackignoreError(f"invalid tree: {'/'.join(dirs[key])!r} is both a file and a "
                                  f"directory")
        if key in merged:
            merged[key][1] = content
        else:
            merged[key] = [spelled + (parts[-1],), content]
    return {"/".join(spelled): content for spelled, content in merged.values()}


def _expand_braces(pattern):
    start = pattern.find("{")
    if start < 0:
        return [pattern]
    end = pattern.find("}", start)
    if end < 0:
        return [pattern]
    head = pattern[:start]
    rests = _expand_braces(pattern[end + 1:])
    return [head + alt + rest for alt in pattern[start + 1:end].split(",") for rest in rests]


